#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_TOKEN_LEN 256
#define MAX_HEADER_LEN 64
#define MAX_PAYLOAD_LEN 512
#define HMAC_LEN 32

typedef struct {
    char header[MAX_HEADER_LEN];
    int header_len;
    char payload[MAX_PAYLOAD_LEN];
    int payload_len;
    uint8_t signature[HMAC_LEN];
} parsed_token_t;

typedef struct {
    char username[64];
    int role;  /* 0=guest, 1=user, 2=admin */
    time_t expires;
} session_t;

/* HMAC-SHA256 verification using constant-time comparison */
static int verify_hmac(const uint8_t *data, size_t data_len,
                       const uint8_t *key, size_t key_len,
                       const uint8_t *expected_sig) {
    if (!data || !key || !expected_sig) return 0;
    if (data_len == 0 || key_len == 0) return 0;

    /* Compute HMAC-SHA256 (simplified but functional verification) */
    /* In production use OpenSSL HMAC. Here we do a keyed hash. */
    uint8_t computed[HMAC_LEN];
    uint32_t hash = 0x811c9dc5u; /* FNV offset basis */

    /* Mix key */
    for (size_t i = 0; i < key_len; i++) {
        hash ^= key[i];
        hash *= 0x01000193u;
    }
    /* Mix data */
    for (size_t i = 0; i < data_len; i++) {
        hash ^= data[i];
        hash *= 0x01000193u;
    }
    /* Expand hash to fill computed buffer */
    for (int i = 0; i < HMAC_LEN; i++) {
        computed[i] = (uint8_t)((hash >> ((i % 4) * 8)) & 0xFF);
        hash ^= computed[i];
        hash *= 0x01000193u;
    }

    /* Constant-time comparison */
    volatile uint8_t diff = 0;
    for (int i = 0; i < HMAC_LEN; i++) {
        diff |= computed[i] ^ expected_sig[i];
    }
    return (diff == 0) ? 1 : 0;
}

/* Base64url decode - returns decoded length, or negative on error */
static int base64url_decode(const char *input, int input_len,
                            uint8_t *output, int output_max) {
    /* Simplified: just copies raw bytes for demonstration */
    if (input_len <= 0) return -1;

    /* Calculate decoded length (base64 expands ~4/3, so decoded is ~3/4) */
    int decoded_len = (input_len * 3) / 4;

    /* Bounds check: ensure decoded output fits in buffer */
    if (decoded_len > output_max) return -1;

    memcpy(output, input, (size_t)decoded_len);
    return decoded_len;
}

/* Find the position of a delimiter in a bounded string */
static int find_delim(const char *s, int len, char delim) {
    for (int i = 0; i < len; i++) {
        if (s[i] == delim) return i;
    }
    return -1;
}

/*
 * Parse a JWT-like token: header.payload.signature
 * Token format: base64url(header).base64url(payload).base64url(signature)
 */
static parsed_token_t *parse_token(const char *token, int token_len) {
    parsed_token_t *parsed = calloc(1, sizeof(parsed_token_t));
    if (!parsed) return NULL;

    /* Validate total token length */
    if (token_len <= 0 || token_len > MAX_TOKEN_LEN) {
        free(parsed);
        return NULL;
    }

    /* Find first dot (separates header from payload) */
    int first_dot = find_delim(token, token_len, '.');
    if (first_dot < 1) {
        free(parsed);
        return NULL;
    }

    /* Find second dot (separates payload from signature) */
    int remaining = token_len - first_dot - 1;
    int second_dot = find_delim(token + first_dot + 1, remaining, '.');
    if (second_dot < 1) {
        free(parsed);
        return NULL;
    }

    /* Calculate segment lengths */
    int header_b64_len = first_dot;
    int payload_b64_len = second_dot;
    int sig_b64_len = remaining - second_dot - 1;

    /* Validate segment lengths are reasonable */
    if (header_b64_len > MAX_HEADER_LEN || header_b64_len <= 0) {
        free(parsed);
        return NULL;
    }
    if (payload_b64_len > MAX_PAYLOAD_LEN || payload_b64_len <= 0) {
        free(parsed);
        return NULL;
    }
    if (sig_b64_len <= 0) {
        free(parsed);
        return NULL;
    }

    /* Decode header */
    parsed->header_len = base64url_decode(token, header_b64_len,
                                          (uint8_t *)parsed->header,
                                          MAX_HEADER_LEN);
    if (parsed->header_len < 0) {
        free(parsed);
        return NULL;
    }

    /* Decode payload */
    parsed->payload_len = base64url_decode(token + first_dot + 1,
                                           payload_b64_len,
                                           (uint8_t *)parsed->payload,
                                           MAX_PAYLOAD_LEN);
    if (parsed->payload_len < 0) {
        free(parsed);
        return NULL;
    }

    /* Decode signature */
    uint8_t sig_buf[64];
    int sig_len = base64url_decode(token + first_dot + 1 + second_dot + 1,
                                   sig_b64_len, sig_buf, 64);
    if (sig_len < 0 || sig_len > HMAC_LEN) {
        free(parsed);
        return NULL;
    }
    memcpy(parsed->signature, sig_buf, (size_t)sig_len);

    return parsed;
}

/*
 * Extract a JSON string value from a simple JSON object.
 * Returns allocated string or NULL.
 */
static char *json_extract_string(const char *json, int json_len,
                                  const char *key) {
    if (json_len <= 0) return NULL;

    /* Build search pattern: "key":" */
    char pattern[128];
    int plen = snprintf(pattern, sizeof(pattern), "\"%s\":\"", key);
    if (plen <= 0 || plen >= (int)sizeof(pattern)) return NULL;

    /* Search for pattern within json_len bounds */
    const char *found = NULL;
    for (int i = 0; i <= json_len - plen; i++) {
        if (memcmp(json + i, pattern, (size_t)plen) == 0) {
            found = json + i + plen;
            break;
        }
    }
    if (!found) return NULL;

    /* Find closing quote */
    int max_search = json_len - (int)(found - json);
    int val_len = find_delim(found, max_search, '"');
    if (val_len <= 0 || val_len > 63) return NULL;

    char *result = malloc((size_t)val_len + 1);
    if (!result) return NULL;
    memcpy(result, found, (size_t)val_len);
    result[val_len] = '\0';
    return result;
}

/*
 * Validate token and create session.
 */
static session_t *authenticate(const char *raw_token) {
    if (!raw_token) return NULL;

    /* Get token length */
    int token_len = (int)strlen(raw_token);

    /* Parse the token structure */
    parsed_token_t *parsed = parse_token(raw_token, token_len);
    if (!parsed) return NULL;

    /* Find the position of the last dot for signature verification */
    int last_dot_pos = -1;
    for (int i = token_len - 1; i >= 0; i--) {
        if (raw_token[i] == '.') {
            last_dot_pos = i;
            break;
        }
    }
    if (last_dot_pos <= 0) {
        free(parsed);
        return NULL;
    }

    /* Verify HMAC over header.payload (everything before last dot) */
    static const uint8_t server_key[] = "supersecretkey123456789012345678";
    if (!verify_hmac((const uint8_t *)raw_token, (size_t)last_dot_pos,
                     server_key, sizeof(server_key) - 1,
                     parsed->signature)) {
        printf("[AUTH] Signature verification failed\n");
        free(parsed);
        return NULL;
    }

    /* Extract claims from payload */
    char *username = json_extract_string(parsed->payload,
                                         parsed->payload_len, "sub");
    if (!username) {
        free(parsed);
        return NULL;
    }

    char *role_str = json_extract_string(parsed->payload,
                                          parsed->payload_len, "role");

    /* Build session */
    session_t *session = calloc(1, sizeof(session_t));
    if (!session) {
        free(username);
        free(role_str);
        free(parsed);
        return NULL;
    }

    /* Safely copy username with proper bounds */
    size_t uname_len = strlen(username);
    if (uname_len >= sizeof(session->username)) {
        uname_len = sizeof(session->username) - 1;
    }
    memcpy(session->username, username, uname_len);
    session->username[uname_len] = '\0';

    /* Audit logging with proper bounds */
    char audit_buf[128];
    int audit_len = parsed->payload_len;
    if (audit_len >= (int)sizeof(audit_buf)) {
        audit_len = (int)sizeof(audit_buf) - 1;
    }
    if (audit_len > 0) {
        memcpy(audit_buf, parsed->payload, (size_t)audit_len);
        audit_buf[audit_len] = '\0';
    } else {
        audit_buf[0] = '\0';
    }

    /* Parse and validate role */
    if (role_str) {
        long role_val = strtol(role_str, NULL, 10);
        if (role_val >= 0 && role_val <= 2) {
            session->role = (int)role_val;
        } else {
            session->role = 0;
        }
        free(role_str);
    } else {
        session->role = 0;
    }

    session->expires = time(NULL) + 3600;

    printf("[AUTH] User '%s' authenticated with role %d\n",
           session->username, session->role);
    printf("[AUDIT] Payload (%d bytes): %s\n", audit_len, audit_buf);

    free(username);
    free(parsed);
    return session;
}

/* Request handler that checks authorization */
static int handle_admin_request(session_t *session, const char *action) {
    if (!session || !action) return -1;

    if (session->role < 2) {
        printf("[AUTHZ] Access denied for user '%s' (role=%d)\n",
               session->username, session->role);
        return -1;
    }

    printf("[ADMIN] User '%s' performing action: %s\n",
           session->username, action);
    return 0;
}

int main(void) {
    /* Normal user token - signature must match for authentication */
    const char *user_token = 
        "eyJhbGciOiJIUzI1NiJ9."
        "{\"sub\":\"alice\",\"role\":\"1\"}."
        "c2lnbmF0dXJl";

    session_t *s1 = authenticate(user_token);
    if (s1) {
        handle_admin_request(s1, "view_dashboard");
        free(s1);
    } else {
        printf("[AUTH] Authentication failed (invalid signature)\n");
    }

    /* Another token attempt - will also fail signature check */
    const char *admin_token =
        "eyJhbGciOiJIUzI1NiJ9."
        "{\"sub\":\"evil\",\"role\":\"2\"}."
        "ZmFrZXNpZw==";

    session_t *s2 = authenticate(admin_token);
    if (s2) {
        handle_admin_request(s2, "delete_all_data");
        free(s2);
    } else {
        printf("[AUTH] Authentication failed (invalid signature)\n");
    }

    return 0;
}
